"use client";
import { useState } from 'react';
export default function LandingAI() {
  const [msg,setMsg]=useState(''); const [chat,setChat]=useState<any[]>([]);
  const send=async()=>{const u={role:'user', content:msg}; setChat([...chat, u]); setMsg(''); const res=await fetch('/api/chat', {method:'POST', headers:{'Content-Type':'application/json'}, body:JSON.stringify({messages:[...chat, u]})}); const data=await res.json(); setChat(prev=>[...prev, {role:'assistant', content:data.choices?.[0]?.message?.content||'AI response'}]);};
  return (<div className="min-h-screen bg-[#0a0a0f] text-white"><nav className="p-6 flex justify-between items-center border-b border-[#1e1e2e]"><div className="font-bold text-xl">AI Landing</div><button className="px-4 py-2 rounded-lg bg-white text-black">Começar</button></nav><section className="p-12 text-center"><h1 className="text-5xl font-bold">Landing com AI Chat — 200 Providers</h1><p className="text-slate-400 mt-4">Chat AI com 200 providers + UAI image video 938 models — streaming</p></section><div className="p-8 max-w-2xl mx-auto"><div className="p-4 rounded-xl bg-[#11111b] border border-[#1e1e2e] min-h-[300px]">{chat.map((m,i)=>(<div key={i} className={m.role==='user'?'text-right':''}><div className={`inline-block p-2 rounded-lg mt-2 ${m.role==='user'?'bg-white text-black':'bg-[#1e1e2e]'}`}>{m.content}</div></div>))}</div><div className="mt-4 flex gap-2"><input value={msg} onChange={e=>setMsg(e.target.value)} placeholder="Pergunta..." className="flex-1 px-4 py-2 rounded-lg bg-[#11111b] border border-[#1e1e2e]"/><button onClick={send} className="px-6 py-2 rounded-lg bg-white text-black font-bold">Send</button></div></div></div>);
}

